This is related to How to disable OMP in a translation unit at the source file? . The patch I am working on has the following due to benchmarking results. It appears we need the ability to turn off OMP on the translation unit: static const bool CRYPTOPP_RW_USE_OMP = true;
...

ModularArithmetic modp(m_p), modq(m_q);

#pragma omp parallel sections if(CRYPTOPP_RW_USE_OMP)
{
    #pragma omp section
        m_pre_2_9p = modp.Exponentiate(2, (9 * m_p - 11)/8);
    #pragma omp section
        m_pre_2_3q = modq.Exponentiate(2, (3 * m_q - 5)/8);
    #pragma omp section
        m_pre_q_p = modp.Exponentiate(m_q, m_p - 2);
} The patch also applies to a cross platform library (Linux, Unix, Solaris, BSDs, OS X and Windows), and it supports a lot of older compilers. I need to ensure that I don't break a compile. Question : how portable is the #pragma omp parallel sections if(CRYPTOPP_RW_USE_OMP) ? Will using it break compiles that used to work with just #pragma omp parallel sections ? I tried looking at past OpenMP specifications, like 2.0 , but I can't see where its allowed in the grammar (see Appendix C). The closest I could find is the parallel-directive production (line 22), which leads to parallel-clause (line 24) and then unique-parallel-clause . And looking at documentation for platforms I can't test on, its not clear to me if its available. For example, Microsoft's documentation for Visual Studio 2005 appears to only allow it on a loop .

I'm trying to make use of openmp to parallelise the function below in creating a 3D grid. Classes Point, Triangle, and Box have been declared & structured but the code is not pasted here as it's quite long to include in the question (about 110 lines). If you need it and allow me to paste it, then I can edit this question. I've tried using #pragma omp parallel for on the outermost for() loop and the program crashed as I run it. Then, I tried implementing the following #pragma codes below and the program took a longer time to run it (compared to the serial coding). I referred to this link here in implementing it. Actually first of all, is it possible to parallelise the code below using openmp? If yes, then I really need your help in this. int main()
{
    vector<Box> boxes;
    Triangle dummy1;

    float dx = 81.0, dy = 121.0, dz = 98.0, delta=1.0;
    long int nx = 5*ceil(dx/(5.0*delta));
    long int ny = 5*ceil(dy/(5.0*delta));
    long int nz = 5*ceil(dz/(5.0*delta));
    long int Box_ID=1, Pt_ID=1;
    float x_val=0.0, y_val=0.0, z_val=0.0;
    float x0=-42.0f, y0=-3.0f, z0=-52.0f;

    long int i, j, k;
    for(i=0; i<nz+2; i++)
    {
        z_val=i*delta + z0;
        for(j=0; j<ny+2; j++)
        {
            y_val=j*delta + y0;
            #pragma omp parallel
            {
                vector<Box> box_private;
                #pragma omp for nowait schedule(static)
                for(k=0; k<nx+2; k++)
                {
                    x_val=k*delta + x0;
                    Point x1(x_val, y_val, z_val, Pt_ID);
                    Point x2(x_val+delta, y_val, z_val, Pt_ID+1);
                    Point x3(x_val, y_val+delta, z_val, Pt_ID+2);
                    Point x4(x_val+delta, y_val+delta, z_val, Pt_ID+3);
                    Point x5(x_val, y_val, z_val+delta, Pt_ID+4);
                    Point x6(x_val+delta, y_val, z_val+delta, Pt_ID+5);
                    Point x7(x_val, y_val+delta, z_val+delta, Pt_ID+6);
                    Point x8(x_val+delta, y_val+delta, z_val+delta, Pt_ID+7);
                    box_private.push_back(Box(x1,x2,x3,x4,x5,x6,x7,x8,dummy1,Box_ID));
                    Box_ID++;
                    Pt_ID++;
                }
                #pragma omp for schedule(static) ordered
                for(int i=0; i<omp_get_num_threads(); i++)
                {
                    #pragma omp ordered
                    boxes.insert(boxes.end(), box_private.begin(), box_private.end());
                }
            }
        }
    }
} Program crashes when I implement the codes below instead of the above one. #pragma omp parallel for
    for(i=0; i<nz+2; i++)
    {
        z_val=i*delta + z0;
        for(j=0; j<ny+2; j++)
        {
            y_val=j*delta + y0;
            for(k=0; k<nx+2; k++)
            {
                x_val=k*delta + x0;
                /* Point x1 to x8...*/
                boxes.push_back(Box(x1,x2,x3,x4,x5,x6,x7,x8,dummy1,Box_ID));
                Box_ID++;
                Pt_ID++;
            }
        }
    }

answers.body:
The problem with your code is that you don't appreciate the difference between shared and private variables and therefore you have multiple race conditions. 
Variables defined inside a parallel section are private and those defined outside are shared. Since you defined everything outside (except for box_private ) everything is shared (except for box_private and k which OpenMP makes private anyway). But even making the appropriate variables private won't fix your problem because of Box_ID++ and Pt_ID++ . You could fix them with atomic but that's unnecessary and inefficient. If you define Box_ID = ny*nx*i + nx*j + k; (same for Pt_ID ) then your code should work. for(long i=0; i<nz+2; i++) {
    float z_val=i*delta + z0;
    for(long j=0; j<ny+2; j++) {
        float y_val=j*delta + y0;
        #pragma omp parallel
        {
            vector<Box> box_private;
            #pragma omp for nowait schedule(static)
            for(long k=0; k<nx+2; k++) {
                float x_val=k*delta + x0;
                long Box_ID = ny*nx*i + nx*j + k;
                long Pt_ID  = ny*nx*i + nx*j + k;                    
                Point x1(x_val, y_val, z_val, Pt_ID);
                // Point x2 - x8
                box_private.push_back(Box(x1,x2,x3,x4,x5,x6,x7,x8,dummy1,Box_ID)); But I think you should step back and think a bit about what you want to do. If you know ahead of time how many boxes you will fill then there is no reason to use push_back or a private vector.  In fact you should be able to do #pragma omp parallel for schedule(static)
for(long i=0; i<nz+2; i++) {
    float z_val=i*delta + z0;
    for(long j=0; j<ny+2; j++) {
        float y_val=j*delta + y0;
        for(long k=0; k<nx+2; k++) {
            float x_val=k*delta + x0;
            long Box_ID = ny*nx*i + nx*j + k;
            long Pt_ID  = ny*nx*i + nx*j + k;               
            Point x1(x_val, y_val, z_val, Pt_ID);
            // Point x2 - x8
            boxes[ny*nx*i + nx*j +k] = Box(x1,x2,x3,x4,x5,x6,x7,x8,dummy1,Box_ID);
        }
    }
} where boxes is a C array or if it's a std:vector make sure to resize it. Lastly you can collapse the three loop if you move z_val and y_val insdide the loop over k with x_val and then do #pragma omp parallel for schedule(static) collapse(3) . But you can also do it by hand like this long x = nz + 2, y = ny + 2, z = nx + 2;
#pragma omp parallel for schedule(static)
for(long n=0; n<(x*y*z); n++) {
    long i = n/(y*z);
    long j = (n%(y*z))/z;
    long k = (n%(y*z))%z;
    z_val=i*delta + z0;
    y_val=j*delta + y0;
    x_val=k*delta + x0;
    Point x1(x_val, y_val, z_val, n+1);
    // Point x2 - x8
    boxes[n] = Box(x1,x2,x3,x4,x5,x6,x7,x8,dummy1,n+1);
} Do you really need Box_ID and Pt_ID then?

The only way to ever guarantee that any compiler will ever emit a particular assembly instruction is to hardcode it.  There's no spec in the world that constrains the compiler to generate specific instructions for a given language feature. Having said that, if support for SSE4.1 or better is specified implicitly or explicitly on the command line, it would greatly surprise me if many compilers emitted SSE2 instructions in situations where the later instructions would work. Checking the assembly isn't difficult: $ cat foo.c
#include <stdio.h>

int main(int argc, char **argv) {

    const int n=128;

    long x[n];
    long y[n];

    for (int i=0; i<n/2; i++) {
        x[i] = y[i] = 1;
        x[i+n/2] = 2;
        y[i+n/2] = 2;
    }

    #pragma omp simd
    for (int i=0; i<n; i++)
        x[i] = (x[i] == y[i]);

    for (int i=0; i<n; i++)
        printf("%d: %ld\n", i, x[i]);

    return 0;
}

$ icc -openmp -msse4.1 -o foo41.s foo.c -S -std=c99 -qopt-report-phase=vec -qopt-report=2
icc: remark #10397: optimization reports are generated in *.optrpt files in the output location
$ icc -openmp -msse2 -o foo2.s foo.c -S -std=c99 -qopt-report-phase=vec -qopt-report=2 -o foo2.s
icc: remark #10397: optimization reports are generated in *.optrpt files in the output location And sure enough: $ grep pcmp foo41.s
    pcmpeqq   (%rax,%rsi,8), %xmm0                          #18.25

$ grep pcmp foo2.s
    pcmpeqd   (%rax,%rsi,8), %xmm2                          #18.25

