#pragma acc kernels loop independent
    for (j = 0; j < num_out; j++)
    {
        double sum = 0;
#pragma acc loop reduction(+:sum)
        for (k = 0; k < num_features; k++)
            sum += (W[j][k] - x[k]) * (W[j][k] - x[k]);
        D[j] = sum;
    }

    double d_min = INFINITY;
    int d_min_idx = -1;

#pragma acc parallel loop reduction(min : d_min)
    for (j = 0; j < num_out; j++)
    {
