{  
    int i,iblk;
    double sum = 0.0,sum1, sum2;

#pragma omp parallel for reduction(+:sum)
    for (i=Nstart;i< Nfinish; i++){
        double x = (i+0.5)*step;
        sum = sum + 4.0/(1.0+x*x); 
    }
    return sum;
