First, as pointed out by Jim Cownie : In all of these answers, b_local is uninitialised, yet you are adding
to it. You need to use calloc instead of malloc Just to add to the accepted answer, I thing you can try the following approach to avoid calling malloc in parallel, and also the overhead of calling #pragma omp atomic . void parallelCSC_SpMV(float *x, float *b, int b_size, int num_threads) {

    float* b_local[num_threads];
    for(int i = 0; i < num_threads; i++) 
       b_local[i] = calloc(b_size, sizeof(float));

    #pragma omp parallel num_threads(num_threads)
    { 
        int tid = omp_get_thread_num();
        #pragma omp for
        for(int i = 0; i < numcols; i++){ 
            for(int j = colptrs[i] - 1; j < colptrs[i+1] - 1; j++){
               float current_add = xrem[j]*x[i];
               int index = irem[j] - 1;
               b_local[tid][index] += current_add;
           }
       }
    }   
    for(int id = 0; id < num_threads; id++)
    {   
        #pragma omp for simd
        for (int k = 0; k < b_size; k++)
        {    
             b[k] += b_local[id][k];
        }
        free(b_local[id]);
    }
} I have not tested the performance of this, so please feel free to do so and provide feedback. You can further optimize by instead of creating a local_b for the master thread just reused the original b , as follows: void parallelCSC_SpMV(float *x, float *b, int b_size, int num_threads) {

    float* b_local[num_threads-1];
    for(int i = 0; i < num_threads-1; i++) 
       b_local[i] = calloc(b_size, sizeof(float));

    #pragma omp parallel num_threads(num_threads)
    { 
        int tid = omp_get_thread_num();
        float *thread_b = (tid == 0) ? b : b_local[tid-1];
        #pragma omp for
        for(int i = 0; i < numcols; i++){ 
            for(int j = colptrs[i] - 1; j < colptrs[i+1] - 1; j++){
               float current_add = xrem[j]*x[i];
               int index = irem[j] - 1;
               thread_b[index] += current_add;
           }
       }
    }   

    for(int id = 0; id < num_threads-1; id++)
    {   
        #pragma omp for simd
        for (int k = 0; k < b_size; k++)
        {    
             b[k] += b_local[id][k];
        }
        free(b_local[id]);
    }
}

