answers.body:
Calling omp_get_num_threads() outside a parallel section will always return 1 , as there is only one active thread at the moment the function is called. The following code should give a correct result, but will be much slower than the serial version due to the large parallelization & synchronization overhead spend for doing a very simple operation. #pragma omp parallel private(x, y) reduction(+:i)//OMP parallel directive
{
    x = drand48();
    y = drand48();
    if((x*x+y*y)<=1.0){i+=1;}
    #pragma omp master
    n+=omp_get_num_threads();
} The following avoids repeatedly spawning threads and may be more efficient, but still probably slower. #pragma omp parallel private(x, y)
while(error>=epsilon){
        x = drand48();
        y = drand48();
        if((x*x+y*y)<=1.0){
            #pragma omp atomic
            i++;
        }
    #pragma omp barrier
    #pragma omp single
    {
        n+=omp_get_num_threads();
        pi_estimate=4.0*(double)i/(double)n;
        error = fabs(M_PI-pi_estimate)/M_PI;
        printf("%lf\n", error);
    } // implicit barrier here
} In order to really go faster, a minimum number of iterations should be given such as: #define ITER 1000
#pragma omp parallel private(x, y)
while(error>=epsilon){
    #pragma omp for reduction(+:i)
    for (int j=1;j<ITER;j++){
        x = drand48();
        y = drand48();
        if((x*x+y*y)<=1.0) i+=1;
    }
    /* implicit barrier + implicit atomic addition
     * of thread-private accumulator to shared variable i
     */

    #pragma omp single
    {
        n+=ITER;
        pi_estimate=4.0*(double)i/(double)n;
        error = fabs(M_PI-pi_estimate)/M_PI;
        printf("%lf\n", error);
    } // implicit barrier
}

