answers.body:
Your code is not guaranteed to get the correct result because it has a race condition.  One way to fix this is to do it out-of-place like this void foo2(int * __restrict a, int * __restrict b) {
    int i;
    #pragma omp parallel for schedule(static)
    for (i = 0; i<N; i++) {
        b[i] = a[i] + a[((i + 1) % N)];
    }   
} If you really want to do it in-place then it's a bit complicated void foo3(int a[]) {    
    int n = N - 1;
    #pragma omp parallel
    {
        int i;
        int ithread = omp_get_thread_num();
        int nthread = omp_get_num_threads();
        int start = ithread*n / nthread;
        int finish = (ithread + 1)*n/ nthread;
        int tmp = a[finish];
        for (i = start; i < finish-1; i++) {
            a[i] += a[i + 1];
        }
        a[finish-1] += tmp;
    }
    a[n] += a[0];
}

