Here are three ways to fix your code Explicitly make j private #pragma omp parallel for reduction(+:sum) private(j)
for (i=0; i<N; ++i) {
    for (j=0; j<N; ++j) {
        sum += A[i][j];
    }
} Change your code and define i and j inside a parallel region #pragma omp parallel reduction(+:sum)
{
    int i,j;
    #pragma omp for
    for (i=0; i<N; ++i) {
        for (j=0; j<N; ++j) {
            sum += A[i][j];
        }
    }
} Use C99 (or GNU99) and change your code to #pragma omp parallel for reduction(+:sum)
for (int i=0; i<N; ++i) {
    for (int j=0; j<N; ++j) {
        sum += A[i][j];
    }
}

