        unsigned char local_digest[MD5_DIGEST_LENGTH];  // changed to local
        MD5(reinterpret_cast<const unsigned char*>(password_str.c_str()), password_str.length(), local_digest);

        std::ostringstream hex_hash;  // moved inside the loop
        for (int j = 0; j < MD5_DIGEST_LENGTH; ++j) {
            hex_hash << std::hex << std::setw(2) << std::setfill('0') << (int)local_digest[j];
        }
        std::string hex_hash_str = hex_hash.str();

        if (hex_hash_str == target) {
            #pragma omp critical
            {
                std::cout << "Original password: " << password_str << std::endl;
                flag = false;
            }
        }

        if (i % 100000 == 0) {
            #pragma omp critical
            {
                std::cout << "Wrong: " << password_str << " " << hex_hash_str << " Trying again..." << std::endl;
            }
        }

        #pragma omp flush(flag)  // improved
        if (!flag) break;
    }
}

The purpose of the while loop is unclear. The program would run infinitely, if no match is found or the while loop would run exactly one time. It is also best practice to specify the number of threads using OMP_NUM_THREADS rather than the clause. The following code tries to abort the OpenMP work-sharing loop with cancellation. If cancellation is not supported, the flag will allow to skip the costly part of the loop while finishing the remaining iteration. This builds on @Rob 's solution #include <cstring>
#include <iomanip>
#include <iostream>
#include <atomic>
#include <omp.h>
#include <openssl/md5.h>
#include <sstream>

int main() {
  std::cout << "Enter hash: ";
  std::string target;
  std::cin >> target;
  std::atomic<bool> flag{false};
#pragma omp parallel for
    for (unsigned long long i = 0; i <= 9999999999ULL; ++i) {
      if (flag)
        continue;
      std::ostringstream password_stream, hex_hash;
      password_stream << std::setfill('0') << std::setw(10) << i;

      std::string password_str = password_stream.str();

      unsigned char digest[MD5_DIGEST_LENGTH];
      MD5(reinterpret_cast<const unsigned char *>(password_str.c_str()),
          password_str.length(), digest);

      for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        hex_hash << std::hex << std::setw(2) << std::setfill('0')
                 << (int)digest[i];
      }
      std::string hex_hash_str = hex_hash.str();

      if (hex_hash_str == target) {
        std::cout << "Orginal password: " << password_str << std::endl;
        flag = true;
        #pragma omp cancel for
        continue;
      }

      if (i % 100000 == 0) {
        std::cout << "Wrong: " << password_str << " " << hex_hash_str
                  << " Trying again..." << std::endl;
      }
    }

  return 0;
} When compiled with -fsanitize=thread , ThreadSanitizer does not report any data race for this version of the code. TSAN_OPTIONS='ignore_noninstrumented_modules=1' OMP_CANCELLATION=true OMP_NUM_THREADS=4 ./a.out enables cancellation and sets the number of threads.

