I have programmed a simulation for the n-body simulation using openMP, where each process represents a single mass Point.
The program compiles fine at the moment, but as you can see, I have several print functions to check the output of individual functions (for example, the accl_a(), which calculates the acceleration of a mass point). During one of these "control" print functions, I noticed that I'm getting the same value for accelerations[0] and accelerations[1], which represent the x and y coordinates, respectively, regardless of different x,y coordinates. This also causes me to get the same values for the velocity[0] and velocity[1]. I have looked over and am unfortunately unable to find the reason for this, so any help (and generally any tips for improvement) are welcome, as I am somewhat of a beginner! #include <stdlib.h>
#include <stdio.h>
#include <unistd.h>
#include <math.h>
#include <time.h>
#include <omp.h>

#define NUM_POINTS 3


// mass Point struct with mass, current pos, & velocity/acceleration arr to store x,y changes

typedef struct massPoint{
    float mass;
    float x, y;
    float velocity[2];
    float acceleration[2];
} massPoint;

// init mass points

void initMassPoint(struct massPoint* point){
    srand(time(NULL));
    int i;

    point->mass = ((float)(rand() % (10000 + 1))/(float)(rand() % (10000 + 1))) * 100;
    point->x = rand() % 200 + 1;
    point->y = rand() % 200 + 1;
    for(i = 0; i < 2; i ++){
        point->acceleration[i] = 0;
        point->velocity[i] = 0;
    }
}

//calculates acceleration of struct a, coordinate x/y

void accel_a(struct massPoint* a, struct massPoint* b, char coordinate){
    float grav_constant = 6.67/1e11;
    float distance, acceleration;

    distance = sqrt( pow((b->x - a->x), 2) + pow((b->y - a->y), 2));
    if(coordinate == 'x'){
        acceleration = a->mass + (grav_constant * a->mass / distance) * (b->x - a->x);
        a->acceleration[0] += acceleration;
    }
    else if(coordinate == 'y'){
        acceleration = a->mass + (grav_constant * a->mass / distance) * (b->y - a->y);
        a->acceleration[1] += acceleration;
    }

}

//calculates new velocity of point a, coorindate x/y

void vel_new(struct massPoint* a, char coordinate){
    float new_vel;
    if(coordinate == 'x'){
        new_vel = a->velocity[0] + a->acceleration[0];
        a->velocity[0] = new_vel;
    }
    else if(coordinate == 'y'){
        new_vel = a->velocity[1] + a->acceleration[1];
        a->velocity[1] = new_vel;
    }
}

//calculates new pos of point a in coordinate x/y
void new_position(struct massPoint* a, char coordinate){
    float new_pos;

    if(coordinate == 'x'){
        new_pos = a->x + a->velocity[0];
        a->x = new_pos;
    }
    else if(coordinate == 'y'){
        new_pos = a->y + a->velocity[1];
        a->y = new_pos;
    }
}


int main(){

    struct massPoint points[NUM_POINTS];
    int i;

    #pragma omp parallel num_threads(NUM_POINTS)
    {
        //init as many points as (NUM_POINTS) & store in arr points

        int id;
        id = omp_get_thread_num();
        initMassPoint(&points[id]);

        #pragma omp barrier //wait until all points succ. initialized, print starting var. of each point

        printf("Mass Point %d: mass=%.2f, x=%f, y=%f\n", id, points[id].mass, points[id].x, points[id].y);
        for(i = 0; i < NUM_POINTS; i++){
            if(id != i){
                #pragma omp critical 
                {
                    accel_a(&points[id], &points[i], 'x');
                    accel_a(&points[id], &points[i], 'y');

                }   
            }
        }
        #pragma omp barrier

        printf("New acceleration for Mass Point %d: x=%f, y=%f\n", id, points[id].acceleration[0], points[id].acceleration[1]);
        vel_new(&points[id], 'x');
        vel_new(&points[id], 'y');
        printf("vel for %d x = %f, y = %f \n", id, points[id].velocity[0], points[id].velocity[1]);

